Method.Implementation:
 set ServiceName = "GetSettingsDiffReport"	

 set message = "Differences in Component Settings - <I> System: " _ $SYSTEM _ ", Date: " _ $ZDATETIME($HOROLOG,3, 1)  _ "</I><br /><br />"
 set num =1
 set sendEmail = 0
 set tSc = $$$OK
 set svnUser = ""
 set svnPassWd = ""
 try {

  		$$$LOGINFO("Start IHC.ITF.ITFCOMMON.Task.GetSettingsDiffReport")
  		Do ##class(IHC.ITF.ITFCOMMON.Utility).ClearItfDebug($USERNAME)
  		Set $NAMESPACE = "ITFCOMMON"

  		// set message =  message _ " Namespace: <B>" _ $NAMESPACE _"</B><br />"
  		 set statement=##class(%SQL.Statement).%New()
		 set stat=statement.%Prepare("Select ID,Username, Password,BusinessPartner from Ens_Config.Credentials where ID = '" _ ..Credential _"'")
		 if $$$ISERR(stat) { 

		 	return $$$ERROR("Could not find Credentials: " _ ..Credential)
		 }
		 else
		 {
			 set resultset=statement.%Execute()
			 while resultset.%Next() {

			    set svnUser = resultset.%Get("Username")
			    set svnPassWd = resultset.%Get("Password")
			 }
			 Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFileWithUserNm($USERNAME, "Using user to access SubVersion : " _ svnUser _ ", Process.UserName: " _ $USERNAME)

		 }

  		set env = ""
		set sysEnv = $ZCVT($SYSTEM, "U")
		if ( $FIND(sysEnv, "PRD") > 0)
		{
			set env = "PROD"
		}
		elseif ( $FIND(sysEnv, "UAT") > 0)
		{
			set env = "UAT"
		}
		elseif ( $FIND(sysEnv, "QA") > 0)
		{
			set env = "QA"
		}
		else
		{
			set env = "DEV"
		}

		  set newDirec = "/itf-share/itf-tmp/itfSvnFiles/ITF_EnsembleReleasePkgs/batch/" _ env _ "/"
		  set svnDirec =  "/itf-share/itf-tmp/GetSettingsDiffReport/svn/" 
		  set message =  message _  "<B>Comparing Today's export files in </B>" 
		  set message =  message _  "   -- " _ newDirec
		  set message =  message _  "<B> WITH files in SVN </B>"
		  set message =  message _  "   -- " _ svnDirec _ "<br /><br />"

		  set fileCnt = 0
		  set fileNotFound = 0
		  SET LfileNotFound=$LISTBUILD("")

		  set numDiff = 0
		  // 
		  		set rmCmd = "rm -rf " _ svnDirec 
				Set stat = ##class(IHC.ITF.SrcCtrlPkg.EnsembleSrcCtrlClass).ExecuteShellCmd(rmCmd)

		  	 	Set stat =  ..CheckSvnSetup(svnDirec, svnUser, svnPassWd)
		  	 	if ($$$ISERR(stat))
		  	 	{
			  	 	Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFileWithUserNm($USERNAME, "SVN setup failed")
			  	 	return stat
		  	 	}

			 	set rmCmd = "rm -rf " _ newDirec 
				Set stat = ##class(IHC.ITF.SrcCtrlPkg.EnsembleSrcCtrlClass).ExecuteShellCmd(rmCmd)
				// set message =  message _  ", Delete directory: " _ stat

			 	Set stat =  ##class(IHC.ITF.ITFCOMMON.Util.createSettingsFiles).CreateSettingFiles()
			 	// set message =  message _  ", CreateSettingFiles: " _ stat

			 	set svnDirec =  svnDirec _ env _ "/"
			 	set diffFile = 	##class(%Library.File).TempFilename()
			 	set grpFile = 	##class(%Library.File).TempFilename()
			 	Set tRS = ##class(%ResultSet).%New("%File:FileSet")
		 		Set tSC = tRS.Execute(newDirec)
		        For {
		            Quit:'tRS.Next()
		            set fNm = tRS.Get("Name")
		            set fileCnt = fileCnt + 1
		            set NewfName = svnDirec _ $PIECE(fNm,"/",*)
		            // set message =  message _   fNm 
		            if ( ##class(%File).Exists(NewfName))
		            {
			            Set diff = ##class(%File).Compare(fNm, NewfName)
			            if (' diff)
			            {
				            Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFileWithUserNm($USERNAME, "Running diff for " _ fNm)
				            set sendEmail = 1
				            set cmd = "diff -w -B --suppress-common-lines " _ fNm _ " '" _ NewfName _ "' > " _ diffFile

						    Set stat = ##class(IHC.ITF.SrcCtrlPkg.EnsembleSrcCtrlClass).ExecuteShellCmd( cmd)

						    Set file=##class(%File).%New(diffFile)
						    if (file.Size > 0)
						    {
							    set cmd = "grep -v -E '" _ ..excludePattern _ "' "_ diffFile _ " > " _ grpFile
							    Set stat = ##class(IHC.ITF.SrcCtrlPkg.EnsembleSrcCtrlClass).ExecuteShellCmd( cmd)
							    Set file=##class(%File).%New(grpFile)
							    if (file.Size > 0)
							    {

									 Do file.Open("R")
									 set diffMessage = ""
									 While 'file.AtEnd 
								     {
									     set diffLn = file.ReadLine(, .sc, .stat)
									     if (diffLn [ "<") ||  (diffLn [ ">")
									     {
										     set diffMessage =  diffMessage _  "<br />  " _ diffLn
									     }
								     }
								     Do file.Close()
								     if $L(diffMessage) > 0
									 {
									     set numDiff = numDiff + 1
										 set message =  message _ "<br /><B>" _ numDiff _ ". DIFF in " _ $PIECE(fNm,"/",*) _ " --- </B>"

									   	 set message =  message  _ diffMessage _  "<br />  "
									 }

							    }
						    }

					     }

		            }
		            else
		            {
			            // set message =  message _  " -- NOT FOUND: " _ NewfName
			            set fileNotFound = fileNotFound + 1
			            SET $LIST(LfileNotFound, fileNotFound) = NewfName
			            set sendEmail = 1
			            Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFileWithUserNm($USERNAME, " SVn file not found: " _NewfName)
		            }

		       }
		 	   Do tRS.Close()
		 	   Do ##class(%File).Delete(diffFile)
		 	   Do ##class(%File).Delete(grpFile)


			set message =  message _  "<br />--- List of components without setting files in SVN:"
			SET ptr=0,count=0
		    WHILE $LISTNEXT(LfileNotFound,ptr,value) {
		      SET count=count+1
		      if ($L(value) > 0)
		      {
		      	set message =  message _ "<br />" _ count _". " _ value 
		      }
		   }
		   set message =  message _  "<br />---"
		   set message =  message _  "<br />System: " _ sysEnv
		   set message =  message _  "<br /> Number of Components in Ensemble: " _ fileCnt 
		   set message =  message _  "<br />  Settings files not found in SVN: " _ fileNotFound  
		   set message =  message _  "<br />  Number of components with settings that are different from SVN: " _ numDiff

			set message =  message _  "<br /><br />-=-= Completed comparing -=-=" 

     } Catch eException {
		set message =  message _  eException.AsStatus()
	}




  	set $NAMESPACE = "ITFCOMMON"
  	$$$LOGINFO( "Send email, message size: " _ $L(message))
  	Set msg = ##class(%Net.MailMessage).%New()
    set msg.From = "itfims@imail.org"

    SET count=$LENGTH(..EmailAddrs, ",")
    SET countup=1
    for reps=1:1:count
    {
	    SET extract=$PIECE(..EmailAddrs, ",", countup)
	    Do msg.To.Insert(extract)
	    SET countup=countup+1
    }


    if (sendEmail = 1)
  	{
	    Set msg.Subject="Components with different settings in SubVersion on " _ $SYSTEM
	    Do msg.TextData.Write(message)
  	}
  	else
  	{
	  	Set msg.Subject="All Components Settings are in sync with SubVersion on " _ $SYSTEM

	    set message =  " - No differences found - <br /> " _ message  
		Do msg.TextData.Write(message)
  	}
    Set msg.IsBinary=0
    Set msg.IsHTML=1


    $$$LOGINFO( "Created message")
    Set adp= ##class(EnsLib.EMail.OutboundAdapter).%New()
    set adp.SMTP = ##class(%Net.SMTP).%New()
    Do adp.SMTPServerSet("smtp.co.ihc.com")
    Do adp.SMTPPortSet(25)

    set tSc= adp.SendMail(msg, .list)
    $$$LOGINFO( "SendMail: " _ tSc)

  return tSc
